def max_repeated_substring_length(N, S):
    from collections import defaultdict

    # Dictionary to store the starting indices of each substring
    substring_indices = defaultdict(list)

    # Iterate through all possible substrings
    for i in range(N):
        for j in range(i + 1, N + 1):
            substring = S[i:j]
            substring_indices[substring].append(i)

    # Find the maximum length of any substring that appears at least twice
    max_length = 0
    for indices in substring_indices.values():
        if len(indices) > 1:
            for i in range(len(indices) - 1):
                for j in range(i + 1, len(indices)):
                    if indices[j] >= indices[i] + len(substring):
                        max_length = max(max_length, len(substring))
                        break

    return max_length

