def can_cross_bridge(weights, bridge_parts, d):
    n = len(weights)
    m = len(bridge_parts)
    total_weight = sum(weights)

    # Check if the total weight is less than or equal to the capacity of the first part
    if total_weight <= bridge_parts[0][1]:
        return True

    # Check if the total weight is greater than the capacity of the last part
    if total_weight > bridge_parts[-1][1]:
        return False

    # Sliding window approach to check feasibility
    for i in range(m):
        left = 0
        right = 0
        current_weight = 0
        while right < n:
            current_weight += weights[right]
            right += 1
            if current_weight > bridge_parts[i][1]:
                return False
            if right - left > bridge_parts[i][0] + 1:
                current_weight -= weights[left]
                left += 1
    return True

