def can_cross_bridge(N, M, weights, bridge_parts):
    # Check if any part of the bridge has a capacity less than the weight of any single camel
    for weight in weights:
        if any(capacity < weight for _, capacity in bridge_parts):
            return False, 0

    # Sort weights in descending order to maximize the distance
    weights.sort(reverse=True)

    # Initialize the minimum distance
    min_distance = 0

    # Iterate through each part of the bridge
    for length, capacity in bridge_parts:
        # Calculate the number of camels that can fit in the current part
        camels_in_part = 0
        current_weight = 0
        for weight in weights:
            if current_weight + weight <= capacity:
                current_weight += weight
                camels_in_part += 1
            else:
                break

        # If no camels can fit, return -1
        if camels_in_part == 0:
            return False, 0

        # Calculate the distance between the first and last camel in the part
        if camels_in_part > 1:
            min_distance += length

    return True, min_distance

