        if x == 0 and y == 0:
            return ""
        if x > 0:
            return "R" + get_mode_sequence(x - 1, y)
        elif x < 0:
            return "L" + get_mode_sequence(x + 1, y)
        elif y > 0:
            return "U" + get_mode_sequence(x, y - 1)
        elif y < 0:
            return "D" + get_mode_sequence(x, y + 1)

    modes = []
    for x, y in points:
