def is_valid_elevator_movement(N, A, B):
    # Initialize the elevator floor and the number of people on the elevator
    current_floor = 1
    people_on_elevator = 0
    elevator_state = [0] * (2 * N + 1)

    for i in range(N):
        a = A[i]
        b = B[i]

        # If A_i or B_i is -1, skip this person
        if a == -1 or b == -1:
            continue

        # Move the elevator to the floor where the person gets on
        while current_floor < a:
            elevator_state[current_floor] = people_on_elevator
            current_floor += 1

        # Person gets on the elevator
        people_on_elevator += 1

        # Move the elevator to the floor where the person gets off
        while current_floor < b:
            elevator_state[current_floor] = people_on_elevator
            current_floor += 1

        # Person gets off the elevator
        people_on_elevator -= 1

    # Move the elevator to the top floor
    while current_floor <= 2 * N:
        elevator_state[current_floor] = people_on_elevator
        current_floor += 1

    # Check if the elevator state is consistent
    for i in range(1, 2 * N):
        if elevator_state[i] != elevator_state[i + 1]:
            return "No"

    return "Yes"

