    num_factors = sum(exponents)

    if num_factors < N:
        return 0

    dp = [[0] * (num_factors + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(num_factors + 1):
            dp[i][j] = dp[i - 1][j]
