    adjacent = []
    if i > 0:
        adjacent.append((i - 1, j))
    if i < H - 1:
        adjacent.append((i + 1, j))
    if j > 0:
        adjacent.append((i, j - 1))
    if j < W - 1:
        adjacent.append((i, j + 1))
    return adjacent

