def matrix_multiply(A, B):
    return np.dot(A, B) % MOD

def matrix_power(matrix, k):
    result = np.eye(len(matrix), dtype=int)
    base = matrix
    while k > 0:
        if k % 2 == 1:
            result = matrix_multiply(result, base)
        base = matrix_multiply(base, base)
        k //= 2
    return result

