    transition = np.zeros((n, n), dtype=int)
    for i in range(n):
        for j in range(n):
            if i != j:
                transition[i][j] = 1

    # Compute the transition matrix raised to the power of k
    transition_k = matrix_power(transition, k)

    # The number of ways to distribute n people in n rooms after k moves
    return np.sum(transition_k) % MOD

