def find_induced_subgraph(N, M, edges):
    from collections import defaultdict, deque

    # Build the adjacency list
    graph = defaultdict(list)
    in_degree = [0] * (N + 1)
    out_degree = [0] * (N + 1)

    for A, B in edges:
        graph[A].append(B)
        in_degree[B] += 1
        out_degree[A] += 1

    # Check for cycles where each vertex has in-degree and out-degree of 1
    for start in range(1, N + 1):
        if in_degree[start] == 1 and out_degree[start] == 1:
            cycle = []
            visited = set()
            stack = [start]

            while stack:
                node = stack[-1]
                if node in visited:
                    cycle.append(node)
                    stack.pop()
                else:
                    visited.add(node)
                    stack.append(graph[node][0])

            if len(cycle) > 1 and all(in_degree[v] == 1 and out_degree[v] == 1 for v in cycle):
                return cycle

    return -1

