def is_valid_painting(color, tree, restrictions):
    for u, v in restrictions:
        if u > v:
            u, v = v, u
        stack = [u]
        visited = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if node == v:
