def count_valid_paintings(N, edges, M, restrictions):
    tree = defaultdict(list)
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    parent = [-1] * (N + 1)
    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

    rank = [0] * (N + 1)
    for a, b in edges:
        union(parent, rank, a, b)

    color = [0] * (N + 1)
    def backtrack(node, parent):
        if node == N + 1:
            if is_valid_painting(color, tree, restrictions):
                return 1
            return 0
        count = 0
        for c in [0, 1]:
            color[node] = c
            count += backtrack(node + 1, node)
        return count

    return backtrack(1, -1)

