def valid_path(u, v, color, tree):
    stack = [u]
    visited = set()
    while stack:
        current = stack.pop()
        if current == v:
            return True
        visited.add(current)
        for neighbor in tree[current]:
            if neighbor not in visited and color[(current, neighbor)] == 'black':
                stack.append(neighbor)
    return False

