def count_valid_K(N):
    if N == 2:
        return 1
    if N == 3:
        return 2

    # Find all prime factors of N
    prime_factors = set()
    for i in range(2, int(N**0.5) + 1):
        while N % i == 0:
            prime_factors.add(i)
            N //= i
    if N > 1:
        prime_factors.add(N)

    # Count the number of valid K values
    valid_K_count = 0
    for K in range(2, N + 1):
        if any(K % p == 0 for p in prime_factors):
            valid_K_count += 1

    return valid_K_count

