def get_next_matrix(matrix, swaps):
    new_matrix = [row[:] for row in matrix]
    for x, y in swaps:
        for i in range(len(matrix)):
            new_matrix[i][x], new_matrix[i][y] = new_matrix[i][y], new_matrix[i][x]
    return new_matrix

def is_valid(matrix, K):
    for row in matrix:
        if sum(row) > K:
            return False
    for col in zip(*matrix):
        if sum(col) > K:
            return False
    return True

def count_distinct_matrices(N, K, matrix):
    from itertools import combinations

    def generate_swaps():
        for x in range(N):
            for y in range(x + 1, N):
                yield (x, y)

    distinct_matrices = set()
    distinct_matrices.add(tuple(map(tuple, matrix)))

    for swaps in combinations(generate_swaps(), N):
        new_matrix = get_next_matrix(matrix, swaps)
        if is_valid(new_matrix, K):
            distinct_matrices.add(tuple(map(tuple, new_matrix)))

    return len(distinct_matrices) % MOD

