def count_permutations(matrix, N, K):
    def is_valid_permutation(perm):
        for i in range(N):
            for j in range(i + 1, N):
                if matrix[i][perm[j]] + matrix[i][perm[i]] > K:
                    return False
                if matrix[perm[i]][j] + matrix[perm[j]][i] > K:
                    return False
        return True

    def backtrack(row, used):
        if row == N:
            return 1
        count = 0
        for col in range(N):
            if col not in used:
                used.add(col)
                if is_valid_permutation(used):
                    count = (count + backtrack(row + 1, used)) % MOD
                used.remove(col)
        return count

    return backtrack(0, set())

