    for i in range(N):
        for j in range(N):
            for k in range(j + 1, N):
                if matrix[i][j] + matrix[i][k] <= K:
                    union(parent_row, rank_row, j, k)

    # Union elements in the same column if their sum is <= K
    for j in range(N):
        for i in range(N):
            for k in range(i + 1, N):
                if matrix[i][j] + matrix[k][j] <= K:
                    union(parent_col, rank_col, i, k)

    # Count the number of distinct groups for rows and columns
    row_groups = {}
    col_groups = {}
    for i in range(N):
        root_i = find(parent_row, i)
        if root_i not in row_groups:
            row_groups[root_i] = 0
        row_groups[root_i] += 1

    for j in range(N):
        root_j = find(parent_col, j)
        if root_j not in col_groups:
            col_groups[root_j] = 0
        col_groups[root_j] += 1

    # Calculate the number of distinct matrices
    result = 1
    for size in row_groups.values():
        result = (result * size) % MOD
    for size in col_groups.values():
        result = (result * size) % MOD

