def can_schedule_matches(N, adj_list):
    # Step 1: Check for cycles using DFS
    visited = [False] * (N + 1)
    rec_stack = [False] * (N + 1)

    def dfs(node):
        if rec_stack[node]:
            return True
        if visited[node]:
            return False
        visited[node] = True
        rec_stack[node] = True
        for neighbor in adj_list[node]:
            if dfs(neighbor):
                return True
        rec_stack[node] = False
        return False

    for i in range(1, N + 1):
        if not visited[i]:
            if dfs(i):
                return -1

    # Step 2: Perform topological sort using Kahn's algorithm
    in_degree = [0] * (N + 1)
    for i in range(1, N + 1):
        for neighbor in adj_list[i]:
            in_degree[neighbor] += 1

    queue = deque([i for i in range(1, N + 1) if in_degree[i] == 0])
    days = 0
    topo_order = []

    while queue:
