def is_valid(choices, a):
    for i in range(1, len(choices) + 1):
        total = sum(choices[j] for j in range(len(choices)) if (j + 1) % i == 0)
        if total % 2 != a[i - 1]:
            return False
    return True

def find_choices(N, a):
    choices = [0] * N

    def backtrack(index):
        if index == N:
            if is_valid(choices, a):
                return choices[:]
            return None

        # Try putting a ball in the current box
        choices[index] = 1
        result = backtrack(index + 1)
        if result is not None:
            return result

        # Try not putting a ball in the current box
        choices[index] = 0
        result = backtrack(index + 1)
        if result is not None:
            return result

        return None

    result = backtrack(0)
    return result

