def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def derangement(n):
    if n == 0:
        return 1
    if n == 1:
        return 0
    result = 0
    for i in range(n + 1):
        if i % 2 == 0:
            result = (result + factorial(n) // factorial(i)) % MOD
        else:
            result = (result - factorial(n) // factorial(i)) % MOD
    return result

def count_pairs(N, M):
    if N > M:
        return 0
    return derangement(N)

