def count_valid_sequences(N, M):
    if N > M:
        return 0

    # Initialize dp table
    dp = [[0] * (M + 1) for _ in range(N + 1)]

    # Base case: sequences of length 1
    for j in range(1, M + 1):
        dp[1][j] = 1

    # Fill dp table
    for i in range(2, N + 1):
        for j in range(1, M + 1):
            dp[i][j] = sum(dp[i-1][k] for k in range(1, M + 1) if k != j) % MOD

    # Calculate the total number of valid pairs of sequences
    total_count = 0
    for j in range(1, M + 1):
        for k in range(1, M + 1):
            if j != k:
                total_count = (total_count + dp[N][j] * dp[N][k]) % MOD

    return total_count

