def min_spanning_tree(n, edges):
    visited = [False] * n
    mst = 0
    pq = [(0, 0)]
    while pq:
        weight, u = heapq.heappop(pq)
        if visited[u]:
            continue
        visited[u] = True
        mst += weight
        for v, w in edges[u]:
            if not visited[v]:
                heapq.heappush(pq, (w, v))
    return mst

