def can_reach_target(N, S):
    if N == 0:
        return len(S) == 0
    if N == 1:
        return len(S) == 1

    target_count = Counter(S)
    total_slimes = 2 ** N

    def helper(current_count, current_health):
        if sum(current_count.values()) == total_slimes:
            return current_count == target_count

        for new_health in range(1, current_health):
            if new_health in current_count:
                continue
            current_count[new_health] += 1
            if helper(current_count, new_health):
                return True
            current_count[new_health] -= 1

        return False

    return helper(Counter({current_health: 1}), current_health)

