def can_reproduce(multiset):
    if len(multiset) == 1:
        return multiset[0] == 1
    if len(multiset) == 2:
        return multiset[0] == 1 and multiset[1] == 2

    sorted_multiset = sorted(multiset)
    n = len(sorted_multiset)

    @lru_cache(None)
    def can_split(start, end):
        if end - start == 1:
            return sorted_multiset[start] == 1
        if end - start == 2:
            return sorted_multiset[start] == 1 and sorted_multiset[start + 1] == 2

        for i in range(start + 1, end):
            if sorted_multiset[i] < sorted_multiset[start]:
                if can_split(start, i) and can_split(i, end):
                    return True
        return False

    return can_split(0, n)

