def process_queries(N, Q, queries):
    # Initialize the grid
    grid = [[0] * N for _ in range(N)]
    for i in range(1, N-1):
        for j in range(1, N-1):
            grid[i][j] = 1  # Black stones in the central (N-2) x (N-2) square

    # Initialize the bottom and right sides with white stones
    for i in range(N):
        grid[N-1][i] = 0  # Bottom side
        grid[i][N-1] = 0  # Right side

    # Set to keep track of black stones
    black_stones = set()
    for i in range(1, N-1):
        for j in range(1, N-1):
            if grid[i][j] == 1:
                black_stones.add((i, j))

    # Process each query
    for query in queries:
        q_type, x = query
        if q_type == 1:
            # Place a white stone at (1, x) and replace black stones below
            for i in range(1, N):
                if grid[i][x-1] == 0:
                    break
                grid[i][x-1] = 0
                black_stones.discard((i, x-1))
        elif q_type == 2:
            # Place a white stone at (x, 1) and replace black stones to the right
            for j in range(1, N):
                if grid[x-1][j] == 0:
                    break
                grid[x-1][j] = 0
                black_stones.discard((x-1, j))

    # Count the remaining black stones
    return len(black_stones)

