import heapq

def smallest_digit_sum(K):
    # Priority queue to store (digit_sum, multiple)
    pq = [(K, K)]

    while pq:
        current_sum, current_multiple = heapq.heappop(pq)

        # Check if the current multiple is the smallest found so far
        if current_sum == K:
            return current_sum

        # Find the next multiple of K
        next_multiple = current_multiple + K

        # Calculate the digit sum of the next multiple
        next_sum = sum(int(digit) for digit in str(next_multiple))

        # Push the next multiple and its digit sum into the priority queue
        heapq.heappush(pq, (next_sum, next_multiple))

