from collections import defaultdict, deque

def bfs(graph, start, end, blockships):
    queue = deque([start])
    visited = set([start])

    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if neighbor == end:
                return True
            if neighbor not in visited and neighbor not in blockships:
                visited.add(neighbor)
                queue.append(neighbor)

    return False

def count_friend_candidates(N, friendships, blockships):
    graph = defaultdict(list)
    for a, b in friendships:
        graph[a].append(b)
        graph[b].append(a)

    friend_candidates = [0] * (N + 1)

    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if i != j and (i, j) not in friendships and (j, i) not in friendships and (i, j) not in blockships and (j, i) not in blockships:
                if bfs(graph, i, j, blockships):
                    friend_candidates[i] += 1

    return friend_candidates[1:]

