def count_valid_subsets(N, sardines):
    # Dictionary to store dot products and their corresponding pairs
    dot_product_dict = {}

    # Populate the dictionary with dot products
    for i in range(N):
        for j in range(i + 1, N):
            dot_product = sardines[i][0] * sardines[j][0] + sardines[i][1] * sardines[j][1]
            if dot_product not in dot_product_dict:
                dot_product_dict[dot_product] = []
            dot_product_dict[dot_product].append((i, j))

    # Initialize dp array
    dp = [0] * (N + 1)
    dp[0] = 1  # There's one way to choose no sardines

    # Iterate over each sardine
    for i in range(1, N + 1):
        dp[i] = dp[i - 1] * 2  # Each sardine can either be included or not included
        for j in range(i - 1, -1, -1):
            if (j, i - 1) in dot_product_dict:
                dp[i] -= dp[j]
                dp[i] %= MOD

    return dp[N]

