def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    sardines = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(N)]

    # Sort sardines by A_i to handle the constraints efficiently
    sardines.sort()

    # Initialize DP arrays
    dp = [[0, 0] for _ in range(N + 1)]
    dp[0][0] = 1  # No sardines chosen

    for i in range(1, N + 1):
        A, B = sardines[i-1]
        dp[i][0] = (dp[i-1][0] + dp[i-1][1]) % MOD  # Not choosing the current sardine
        dp[i][1] = dp[i-1][0]  # Choosing the current sardine

        # Check for bad terms
        for j in range(i-1):
            A_j, B_j = sardines[j]
            if A * A_j + B * B_j == 0:
                dp[i][1] = (dp[i][1] + dp[j][0]) % MOD
                break

    # The answer is the sum of choosing or not choosing the last sardine
    result = (dp[N][0] + dp[N][1]) % MOD
    print(result)

