def dfs(sardines, visited, index):
    if index in visited:
        return 0
    visited.add(index)
    count = 1
    for i in range(len(sardines)):
        if i != index and sardines[i][0] * sardines[index][0] + sardines[i][1] * sardines[index][1] == 0:
            count += dfs(sardines, visited, i)
    return count

def count_subsets(sardines):
    n = len(sardines)
    if n == 0:
        return 1
    if n == 1:
        return 2

    visited = set()
    total_subsets = 1

    for i in range(n):
        if i not in visited:
            component_size = dfs(sardines, visited, i)
            total_subsets = (total_subsets * (1 << component_size)) % MOD

    return total_subsets

