def count_ways_to_choose_sardines(N, sardines):
    from collections import defaultdict, deque

    # Create adjacency list for the graph
    graph = defaultdict(list)
    for i in range(N):
        for j in range(i + 1, N):
            A_i, B_i = sardines[i]
            A_j, B_j = sardines[j]
            if A_i * A_j + B_i * B_j == 0:
                graph[i].append(j)
                graph[j].append(i)

    # Function to perform DFS and count connected components
    def dfs(node, visited):
        stack = [node]
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                for neighbor in graph[node]:
                    stack.append(neighbor)

    # Find all connected components
    visited = [False] * N
    components = 0
    for i in range(N):
        if not visited[i]:
            dfs(i, visited)
            components += 1

    # Calculate the number of ways to choose subsets for each component
    total_ways = 1
    for _ in range(components):
        total_ways = (total_ways * 2) % MOD

    return total_ways

