class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        pu, pv = self.find(u), self.find(v)
        if pu != pv:
            if self.rank[pu] < self.rank[pv]:
                pu, pv = pv, pu
            self.parent[pv] = pu
            if self.rank[pu] == self.rank[pv]:
                self.rank[pu] += 1

def count_ways(N, sardines):
    uf = UnionFind(N)
    for i in range(N):
        for j in range(i + 1, N):
            A_i, B_i = sardines[i]
            A_j, B_j = sardines[j]
            if A_i * A_j + B_i * B_j == 0:
                uf.union(i, j)

    component_sizes = [0] * N
    for i in range(N):
        component_sizes[uf.find(i)] += 1

    result = 1
    for size in component_sizes:
        if size > 0:
            result = (result * (2**size - 1)) % MOD

    return result

