class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        pu, pv = self.find(u), self.find(v)
        if pu != pv:
            if self.rank[pu] < self.rank[pv]:
                self.parent[pu] = pv
            elif self.rank[pu] > self.rank[pv]:
                self.parent[pv] = pu
            else:
                self.parent[pv] = pu
                self.rank[pu] += 1

def count_independent_sets(n, edges):
    if n == 0:
        return 1
    if n == 1:
        return 2
    uf = UnionFind(n)
    for u, v in edges:
        uf.union(u, v)

    component_sizes = {}
    for i in range(n):
        root = uf.find(i)
        if root not in component_sizes:
            component_sizes[root] = 0
        component_sizes[root] += 1

    result = 1
    for size in component_sizes.values():
        result = (result * (1 << size)) % MOD

    return result

