def dfs(node, visited, graph):
    visited[node] = True
    count = 1
    for neighbor in graph[node]:
        if not visited[neighbor]:
            count += dfs(neighbor, visited, graph)
    return count

def count_ways_to_choose_sardines(N, sardines):
    graph = {i: [] for i in range(N)}

    # Build the graph
    for i in range(N):
        for j in range(i + 1, N):
            A_i, B_i = sardines[i]
            A_j, B_j = sardines[j]
            if A_i * A_j + B_i * B_j == 0:
                graph[i].append(j)
                graph[j].append(i)

    # Find all connected components
    visited = [False] * N
    components = []
    for i in range(N):
        if not visited[i]:
            component_size = dfs(i, visited, graph)
            components.append(component_size)

    # Calculate the number of ways to choose subsets
    total_ways = 1
    for size in components:
        total_ways = (total_ways * (2**size - 1)) % MOD

    return total_ways

