    # Create a dictionary to map each element to its correct position
    correct_positions = {P[i]: i for i in range(N)}

    # Create a list to keep track of the current positions of elements
    current_positions = list(range(N))

    # List to store the sequence of swaps
    swaps = []

    for i in range(N):
        if current_positions[i] != correct_positions[i]:
            # Find the correct position of the current element
            correct_pos = correct_positions[i]

