                # Record the swap
                swaps.append(j)

                # Update the correct position of the current element
                correct_pos = correct_positions[i]

    # If the permutation is not sorted, return -1
    if P != list(range(1, N + 1)):
        return -1

    # Return the sequence of swaps
    return swaps

