    sorted_positions = sorted((P[i], i) for i in range(N))

    # Create a list to keep track of visited positions
    visited = [False] * N

    # Initialize the result list
    result = []

    for value, target_index in sorted_positions:
        if visited[target_index]:
            continue

        # Find the current index of the value
        current_index = P.index(value)

        # If the current index is not the target index, perform swaps
        while current_index != target_index:
            # Swap P[current_index] and P[current_index + 1]
            P[current_index], P[current_index + 1] = P[current_index + 1], P[current_index]
            result.append(current_index + 1)
            current_index += 1

        # Mark the target index as visited
        visited[target_index] = True

    # If all elements are visited, return the result
    if all(visited):
        return result
    else:
        return -1

