def bfs(grid, start, target):
    H, W = len(grid), len(grid[0])
    queue = deque([start])
    visited = set([start])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        x, y = queue.popleft()
        if (x, y) == target:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, H, W) and (nx, ny) not in visited and grid[nx][ny] != '#':
                visited.add((nx, ny))
                queue.append((nx, ny))
    return False

def max_black_cells(grid, start, target):
    H, W = len(grid), len(grid[0])
    dp = [[[-1] * (H * W) for _ in range(W)] for _ in range(H)]
    dp[start[0]][start[1]][0] = 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for k in range(H * W):
        for x in range(H):
            for y in range(W):
                if dp[x][y][k] != -1:
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if is_valid(nx, ny, H, W) and grid[nx][ny] == '.':
                            if dp[nx][ny][k + 1] == -1:
                                dp[nx][ny][k + 1] = dp[x][y][k] + 1
                            else:
                                dp[nx][ny][k + 1] = min(dp[nx][ny][k + 1], dp[x][y][k] + 1)

    max_black = -1
    for k in range(H * W):
        if dp[target[0]][target[1]][k] != -1:
            max_black = k

    return max_black

