def max_changes_to_black(grid, H, W):
    if grid[0][0] == '#' or grid[H-1][W-1] == '#':
        return -1

    if not can_reach_target(grid, H, W):
        return -1

    dp = [[0] * W for _ in range(H)]

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                dp[i][j] = 1

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                if i > 0:
                    dp[i][j] = max(dp[i][j], dp[i-1][j])
                if j > 0:
                    dp[i][j] = max(dp[i][j], dp[i][j-1])

    return dp[H-1][W-1]

