class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1

def min_cost_to_connect_towns(n, towns):
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            cost = min(abs(towns[i][0] - towns[j][0]), abs(towns[i][1] - towns[j][1]))
            edges.append((cost, i, j))

    edges.sort()

    uf = UnionFind(n)
    total_cost = 0
    edges_used = 0

    for cost, u, v in edges:
        if uf.find(u) != uf.find(v):
            uf.union(u, v)
            total_cost += cost
            edges_used += 1
            if edges_used == n - 1:
                break

    return total_cost

