def paint_grid(H, W, N, counts):
    grid = [[0] * W for _ in range(H)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and grid[x][y] == 0

    def paint_color(color, start_x, start_y):
        stack = [(start_x, start_y)]
        grid[start_x][start_y] = color
        count = 1

        while stack and count < counts[color - 1]:
            x, y = stack.pop()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    grid[nx][ny] = color
                    stack.append((nx, ny))
                    count += 1

    for color in range(1, N + 1):
        paint_color(color, 0, 0)

    return grid

