def paint_grid(H, W, N, a):
    grid = [[0] * W for _ in range(H)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and grid[x][y] == 0

    def place_color(color, count):
        x, y = 0, 0
        dx, dy = 0, 1
        while count > 0:
            if is_valid(x, y):
                grid[x][y] = color
                count -= 1
            nx, ny = x + dx, y + dy
            if not is_valid(nx, ny):
                dx, dy = dy, -dx
                nx, ny = x + dx, y + dy
            x, y = nx, ny

    for i in range(1, N + 1):
        place_color(i, a[i - 1])

    for row in grid:
        print(' '.join(map(str, row)))

