def paint_grid(H, W, N, counts):
    grid = [[0] * W for _ in range(H)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    direction_index = 0
    x, y = H // 2, W // 2
    count_index = 0

    for _ in range(H * W):
        grid[x][y] = count_index + 1
        counts[count_index] -= 1
        if counts[count_index] == 0:
            count_index += 1
        dx, dy = directions[direction_index]
        nx, ny = x + dx, y + dy
        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0:
            x, y = nx, ny
        else:
            direction_index = (direction_index + 1) % 4
            dx, dy = directions[direction_index]
            x, y = x + dx, y + dy

    return grid

