def place_color(grid, color, count):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    x, y = H // 2, W // 2
    dx, dy = 0, 1
    placed = 0

    while placed < count:
        grid[x][y] = color
        placed += 1
        if placed == count:
            break
        nx, ny = x + dx, y + dy
        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0:
            x, y = nx, ny
        else:
            dx, dy = directions[(directions.index((dx, dy)) + 1) % 4]
            x, y = x + dx, y + dy

