def paint_grid(H, W, N, a):
    grid = [[0] * W for _ in range(H)]
    color_index = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 0:
                color_index += 1
                grid[i][j] = color_index
                if color_index > N:
                    color_index = 1
                if color_index > N:
                    raise ValueError("Not enough colors to fill the grid")

    # Ensure each color is used exactly a_i times
    for i in range(1, N + 1):
        count = sum(1 for row in grid for cell in row if cell == i)
        if count != a[i - 1]:
            raise ValueError(f"Color {i} is used {count} times, expected {a[i - 1]}")

    # Print the grid
    for row in grid:
        print(" ".join(map(str, row)))

