def paint_grid(H, W, N, a):
    grid = [[0] * W for _ in range(H)]
    color_index = 0

    for i in range(N):
        count = a[i]
        color = i + 1

        # Place the color in a snake-like pattern
        for j in range(count):
            if color_index % 2 == 0:
                grid[j // W][j % W] = color
            else:
                grid[H - 1 - (j // W)][W - 1 - (j % W)] = color
            color_index += 1

    # Print the grid
    for row in grid:
        print(' '.join(map(str, row)))

