def find_unbalanced_substring(s):
    n = len(s)
    for i in range(n):
        char_count = [0] * 26
        for j in range(i, n):
            char_count[ord(s[j]) - ord('a')] += 1
            length = j - i + 1
            if length >= 2 and max(char_count) > length // 2:
                return i + 1, j + 1
    return -1, -1

